 if(!g){
  g=svgEl('g',{'data-piece-key':key,class:'piece-avatar'});
  g.append(svgEl('circle',{cx:0,cy:0,r:23,fill:'#09271d',class:'piece-rim','stroke-width':4}));
  const img=svgEl('image',{href:HODON_FACE,x:-18,y:-18,width:36,height:36,'preserveAspectRatio':'xMidYMid slice','clip-path':'url(#hodon-portrait-clip)'});img.style.pointerEvents='none';g.append(img);
  g.append(svgEl('circle',{cx:0,cy:0,r:18,fill:'none',class:'piece-rim','stroke-width':3,'pointer-events':'none'}));
  g.append(svgEl('rect',{x:-10,y:12,width:20,height:14,rx:6,class:'piece-badge',stroke:'#ffe7a3','stroke-width':1.5}));
  g.append(svgEl('text',{x:0,y:22,'text-anchor':'middle','font-size':12,'font-weight':900,fill:'#fff',class:'piece-count','pointer-events':'none'}));
  g.append(svgEl('circle',{cx:0,cy:0,r:26,fill:'none',stroke:'#9effa9','stroke-width':3,class:'piece-selection','pointer-events':'none'}));
  root.append(g);
 }
 setSvgAttr(g,'data-node',nodeId);setSvgAttr(g,'data-stack',stack);
