 g.removeAttribute('display');g.style.cursor=clickable?'pointer':'default';
 g.querySelectorAll('.piece-rim').forEach(el=>setSvgAttr(el,'stroke',color));setSvgAttr(g.querySelector('.piece-badge'),'fill',color);
 const label=stack>1?`×${stack}`:String(index+1);const count=g.querySelector('.piece-count');if(count.textContent!==label)count.textContent=label;
 setSvgAttr(g.querySelector('.piece-selection'),'display',selected?'inline':'none');
 setSvgAttr(g,'role',clickable?'button':'img');setSvgAttr(g,'aria-label',`${color===COLORS[1]?'청색':color===COLORS[0]?'홍색':'플레이어'} 말 ${index+1}${stack>1?` · ${stack}개 업힘`:''}`);
